const items = $input.all();
const results = [];

// ==========================================
// 1. DECODE HTML ENTITIES
// ==========================================

function decodeHtmlEntities(text) {
  const entities = {
    amp: '&',
    lt: '<',
    gt: '>',
    quot: '"',
    apos: "'",
    nbsp: ' ',
    ndash: '–',
    mdash: '—',
    hellip: '…',
    bull: '•',
    euro: '€',
    copy: '©',
    reg: '®',
    auml: 'ä',
    ouml: 'ö',
    uuml: 'ü',
    Auml: 'Ä',
    Ouml: 'Ö',
    Uuml: 'Ü',
    szlig: 'ß',
    rsquo: '’',
    lsquo: '‘',
    rdquo: '”',
    ldquo: '“'
  };

  return String(text || '').replace(
    /&(#x[0-9a-f]+|#[0-9]+|[a-z][a-z0-9]+);/gi,
    (match, entity) => {

      if (entity.startsWith('#')) {
        const isHex = /^#x/i.test(entity);

        const code = parseInt(
          entity.slice(isHex ? 2 : 1),
          isHex ? 16 : 10
        );

        try {
          return String.fromCodePoint(code);
        } catch {
          return match;
        }
      }

      return entities[entity] ??
        entities[entity.toLowerCase()] ??
        match;
    }
  );
}

// ==========================================
// 2. CONVERT HTML EMAIL TO READABLE TEXT
// ==========================================

function htmlToText(html) {
  let text = String(html || '');

  // Remove HTML head, CSS and scripts
  text = text.replace(
    /<head\b[^>]*>[\s\S]*?<\/head>/gi,
    ''
  );

  text = text.replace(
    /<style\b[^>]*>[\s\S]*?<\/style>/gi,
    ''
  );

  text = text.replace(
    /<script\b[^>]*>[\s\S]*?<\/script>/gi,
    ''
  );

  text = text.replace(
    /<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi,
    ''
  );

  // Remove HTML comments
  text = text.replace(
    /<!--[\s\S]*?-->/g,
    ''
  );

  // Remove hidden preview elements
  text = text.replace(
    /<(div|span|p)\b(?=[^>]*style\s*=\s*["'][^"']*display\s*:\s*none)[^>]*>[\s\S]*?<\/\1>/gi,
    ''
  );

  // Remove images, including tracking pixels
  text = text.replace(
    /<img\b[^>]*>/gi,
    ''
  );

  // Preserve line breaks
  text = text.replace(
    /<br\s*\/?>/gi,
    '\n'
  );

  // Preserve list formatting
  text = text.replace(
    /<li\b[^>]*>/gi,
    '\n• '
  );

  // Preserve paragraphs and headings
  text = text.replace(
    /<\/(?:p|div|h[1-6]|section|article|blockquote)>/gi,
    '\n\n'
  );

  // Preserve table and list structure
  text = text.replace(
    /<\/(?:tr|table|ul|ol|li)>/gi,
    '\n'
  );

  text = text.replace(
    /<\/(?:td|th)>/gi,
    '  '
  );

  // Remove remaining HTML tags
  text = text.replace(
    /<[^>]+>/g,
    ''
  );

  // Decode HTML entities
  text = decodeHtmlEntities(text);

  // Remove invisible formatting characters
  text = text.replace(
    /[\u200B-\u200F\u034F\uFEFF\u2060]/g,
    ''
  );

  // Normalize line endings
  text = text.replace(
    /\r\n?/g,
    '\n'
  );

  // Remove extra spaces without
  // removing paragraph breaks
  text = text.replace(
    /[^\S\n]+/g,
    ' '
  );

  text = text.replace(
    / *\n */g,
    '\n'
  );

  // Remove excessive blank lines
  text = text.replace(
    /\n{3,}/g,
    '\n\n'
  );

  return text.trim();
}

// ==========================================
// 3. PROCESS ALL INCOMING EMAILS
// ==========================================

for (const inputItem of items) {

  const item = inputItem.json;

  // ========================================
  // 4. EXTRACT SENDER INFORMATION
  // ========================================

  let senderName = '';
  let senderEmail = '';

  if (typeof item.from === 'string') {

    senderEmail = item.from;

  } else if (item.from?.emailAddress) {

    senderEmail =
      item.from.emailAddress.address || '';

    senderName =
      item.from.emailAddress.name || '';
  }

  // Fallback to sender object
  if (!senderEmail && item.sender) {

    if (typeof item.sender === 'string') {

      senderEmail = item.sender;

    } else if (item.sender.emailAddress) {

      senderEmail =
        item.sender.emailAddress.address || '';

      senderName =
        senderName ||
        item.sender.emailAddress.name ||
        '';
    }
  }

  // Generate a display name when missing
  if (!senderName && senderEmail) {

    const namePart =
      senderEmail.split('@')[0] || '';

    senderName = namePart
      .replace(/[._-]/g, ' ')
      .replace(/\b\w/g, c => c.toUpperCase());
  }

  // ========================================
  // 5. EXTRACT EMAIL SUBJECT
  // ========================================

  const subject = item.subject || '';
  const ticketReferences = subject.match(/\bNAF-[A-Z0-9]+(?:-[A-Z0-9]+)*\b/gi) || [];
  const ticketRef = (ticketReferences[ticketReferences.length - 1] || '').toUpperCase();

  // ========================================
  // 6. EXTRACT COMPLETE EMAIL BODY
  // ========================================

  let fullBody = '';
  let bodySource = '';

  // First priority: complete Outlook body
  if (
    typeof item.body?.content === 'string' &&
    item.body.content.trim()
  ) {

    fullBody = item.body.content;
    bodySource = 'body.content';

  } else if (
    typeof item.body === 'string' &&
    item.body.trim()
  ) {

    fullBody = item.body;
    bodySource = 'body';

  } else if (
    typeof item.uniqueBody?.content === 'string' &&
    item.uniqueBody.content.trim()
  ) {

    fullBody = item.uniqueBody.content;
    bodySource = 'uniqueBody.content';
  }

  const bodyPreview = item.bodyPreview || '';

  const contentType = String(
    item.body?.contentType ||
    item.uniqueBody?.contentType ||
    ''
  ).toLowerCase();

  let description = '';

  if (fullBody) {

    const isHtml =
      contentType === 'html' ||
      /<(html|body|div|p|br|table|span)\b/i.test(fullBody);

    if (isHtml) {

      description = htmlToText(fullBody);

    } else {

      description = fullBody
        .replace(/\r\n?/g, '\n')
        .trim();
    }

  } else {

    // Only use preview if full body is missing
    description = String(bodyPreview).trim();

    bodySource = 'bodyPreview (INCOMPLETE)';
  }

  // ========================================
  // 7. KEEP COMPLETE DESCRIPTION
  // ========================================

  // NO CHARACTER LIMIT
  // NO SLICE()
  // NO TRUNCATION
  // FULL EMAIL DESCRIPTION IS PRESERVED

  description = String(description || '').trim();

  const descriptionLength =
    Array.from(description).length;

  // ========================================
  // 8. HANDLE EMAIL ATTACHMENTS
  // ========================================

  const binary = {};
  const binaryKeys = [];

  if (inputItem.binary) {

    let i = 0;

    for (
      const key of Object.keys(inputItem.binary)
    ) {

      if (
        key.startsWith('attachment_') ||
        key.startsWith('mediaFiles')
      ) {

        const newKey =
          i === 0
            ? 'mediaFiles'
            : `mediaFiles${i}`;

        binary[newKey] =
          inputItem.binary[key];

        binaryKeys.push(newKey);

        i++;
      }
    }
  }

  const hasAttachments =
    binaryKeys.length > 0;

  const attachmentMetadata = binaryKeys.map((key) => {
    const attachment = inputItem.binary?.[key] || {};
    const rawSize = attachment.fileSize ?? attachment.size ?? 0;
    const parsedSize = typeof rawSize === 'number' ? rawSize : Number.parseInt(String(rawSize), 10);
    return {
      name: String(attachment.fileName || key),
      size: Number.isFinite(parsedSize) ? parsedSize : 0,
      type: String(attachment.mimeType || attachment.fileType || 'application/octet-stream')
    };
  });

  // ========================================
  // 9. RETURN DATA FOR NAF SUPPORT API
  // ========================================

  results.push({

    json: {

      // Customer details
      fullName: senderName,
      email: senderEmail,

      // Email subject
      subject: subject,
      ticketRef: ticketRef,
      receivedDateTime: item.receivedDateTime || new Date().toISOString(),

      // COMPLETE EMAIL DESCRIPTION
      // NO CHARACTER LIMIT
      description: description,

      // Support ticket fields
      requestType: 'other',
      accountType: 'not_collected',
      source: 'Email',

      // Outlook message ID
      messageId: item.id || '',

      // Attachment details
      hasAttachments: hasAttachments,
      binaryKeys: binaryKeys.join(','),
      attachmentMetadata: attachmentMetadata,

      // Debug details
      bodySource: bodySource,

      bodyLength: descriptionLength,

      originalDescriptionLength:
        descriptionLength,

      descriptionTruncated: false,

      fullBodyExtracted:
        Boolean(fullBody)
    },

    // Preserve attachment binary data
    ...(hasAttachments ? { binary } : {})
  });
}

// ==========================================
// 10. RETURN ALL PROCESSED EMAILS
// ==========================================

return results;

