// Deep-extract ticket reference from API response (handles nested objects too)
function findTicketRef(obj) {
  if (!obj || typeof obj !== 'object') return '';

  // Direct field check (most common field names)
  const fields = ['ticketReference', 'ticketRef', 'ticketNumber', 'issueReference', 'issueNumber', 'referenceNumber', 'ticketId', 'id'];

  for (const f of fields) {
    if (obj[f] !== undefined && obj[f] !== null && String(obj[f]).trim()) {
      return String(obj[f]);
    }
  }

  // Check nested 'data', 'result', 'body', 'issue', 'ticket' objects
  for (const nested of ['data', 'result', 'body', 'issue', 'ticket', 'response']) {
    if (obj[nested] && typeof obj[nested] === 'object') {
      const found = findTicketRef(obj[nested]);
      if (found) return found;
    }
  }

  return '';
}

