function normalizeReference(value) {
  return String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function frontendNumericId(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const text = String(value || '').trim();
  if (/^\d+$/.test(text)) return Number(text);
  let hash = 0;
  for (const character of text) {
    hash = ((hash << 5) - hash) + character.charCodeAt(0);
    hash |= 0;
  }
  return Math.abs(hash) % 10000;
}

function derivedDisplayReference(ticket) {
  if (ticket?.id === undefined || ticket?.id === null || ticket.id === '') return '';
  const rawDate = ticket.submittedAt || ticket.createdDateTime || ticket.receivedDateTime || ticket.createdAt || ticket.created_at;
  const parsedDate = rawDate ? new Date(rawDate) : new Date();
  const year = Number.isNaN(parsedDate.getTime()) ? new Date().getUTCFullYear() : parsedDate.getUTCFullYear();
  return 'NAF-' + year + '-' + (1000 + frontendNumericId(ticket.id));
}

function getTicketList(payload) {
  const candidates = [payload, payload.body, payload.data, payload.result, payload.response];
  for (const candidate of candidates) {
    if (Array.isArray(candidate)) return candidate;
    if (!candidate || typeof candidate !== 'object') continue;
    for (const key of ['content', 'data', 'issues', 'tickets', 'results', 'items']) {
      if (Array.isArray(candidate[key])) return candidate[key];
    }
  }
  return [];
}

const wantedReference = normalizeReference(email.ticketRef);
const tickets = getTicketList(response);
const match = tickets.find((ticket) => {
  const references = [
    ticket.ticketReference,
    ticket.ticketRef,
    ticket.ticketNumber,
    ticket.issueReference,
    ticket.issueNumber,
    ticket.referenceNumber,
    ticket.ticketId,
    ticket.reference,
    ticket.number,
    derivedDisplayReference(ticket)
  ];
  return references.some((reference) => {
    const candidate = normalizeReference(reference);
    return candidate && (
      candidate === wantedReference ||
      candidate.endsWith(wantedReference) ||
      wantedReference.endsWith(candidate)
    );
  });
});

const ticketId = match?.id || match?.issueId || match?.ticket?.id || match?.issue?.id || '';

return [{
  json: {
    ...email,
    ticketId: String(ticketId || ''),
    matchedTicket: Boolean(ticketId),
    matchedReference: email.ticketRef,
    matchedTicketCount: tickets.length
  }
}];

const response = $('Authenticate NAF API').first().json || {};
const body = typeof response.body === 'string' ? (() => { try { return JSON.parse(response.body); } catch { return {}; } })() : (response.body || {});
const source = response.data || response.result || body.data || body.result || body || response;
const authToken = source.accessToken || source.access_token || source.token || source.jwt || source.id_token || response.accessToken || response.access_token || response.token || response.jwt || response.id_token || '';
return [{ json: { authToken: String(authToken || '') } }];
